css:
:root { --ci-navy: #1a3352; --ci-accent: #c9a44c; --ci-grey: #6b7280; --ci-line: #dfe3ea; }
.ci-doc { font-family: 'Segoe UI', Tahoma, Arial, sans-serif; color: #1f2937; }
.ci-topbar { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid var(--ci-navy); padding-bottom: 14px; margin-bottom: 18px; }
.ci-topbar .ci-doctitle { text-align: right; }
.ci-topbar h1 { font-size: 1.5em; color: var(--ci-navy); margin: 0 0 2px 0; font-weight: 700; letter-spacing: 0.3px; }
.ci-topbar .ci-doctitle-ar { font-size: 1.1em; color: var(--ci-grey); direction: rtl; }
.ci-topbar .ci-company { font-size: 1.15em; font-weight: 700; color: var(--ci-navy); }
.ci-meta { font-size: 0.85em; color: var(--ci-grey); margin-top: 4px; }
.ci-badge { display: inline-block; background: var(--ci-navy); color: #fff; font-size: 0.75em; padding: 2px 10px; border-radius: 3px; margin-top: 4px; letter-spacing: 0.5px; }
.ci-parties { display: flex; gap: 20px; margin: 16px 0; }
.ci-party-box { flex: 1; border: 1px solid var(--ci-line); border-radius: 4px; padding: 10px 14px; }
.ci-party-box .label { font-size: 0.72em; text-transform: uppercase; letter-spacing: 0.5px; color: var(--ci-grey); margin-bottom: 4px; }
.ci-party-box .label-ar { direction: rtl; font-size: 0.72em; color: var(--ci-grey); float: right; }
.ci-party-box .name { font-weight: 600; font-size: 1.02em; }
.ci-party-box .detail { font-size: 0.85em; color: #374151; margin-top: 2px; }
.ci-items { width: 100%; border-collapse: collapse; margin-top: 6px; font-size: 0.88em; }
.ci-items thead th { background: var(--ci-navy); color: #fff; padding: 7px 8px; font-weight: 600; font-size: 0.82em; text-transform: uppercase; letter-spacing: 0.3px; }
.ci-items tbody td { padding: 7px 8px; border-bottom: 1px solid var(--ci-line); }
.ci-items tbody tr:nth-child(even) { background: #f8f9fb; }
.ci-summary-wrap { display: flex; justify-content: flex-end; margin-top: 14px; }
.ci-summary { width: 340px; }
.ci-summary tr td { padding: 5px 8px; font-size: 0.92em; }
.ci-summary tr td:last-child { text-align: right; }
.ci-summary .ar-line { display: block; direction: rtl; color: var(--ci-grey); font-size: 0.85em; }
.ci-summary .ci-grand { border-top: 2px solid var(--ci-navy); font-weight: 700; font-size: 1.08em; color: var(--ci-navy); }
.ci-summary .ci-grand td { padding-top: 8px; }
.ci-words { margin-top: 10px; font-size: 0.85em; font-style: italic; color: #374151; border-top: 1px dashed var(--ci-line); padding-top: 8px; }
.ci-footer { display: flex; justify-content: space-between; align-items: flex-end; margin-top: 28px; }
.ci-qr-box { text-align: center; }
.ci-qr-box img { border: 1px solid var(--ci-line); padding: 6px; border-radius: 4px; }
.ci-qr-box .cap { font-size: 0.7em; color: var(--ci-grey); margin-top: 4px; }
.ci-sign { display: flex; gap: 60px; }
.ci-sign div { border-top: 1px solid #333; padding-top: 5px; font-size: 0.8em; width: 150px; text-align: center; }
.ci-note { font-size: 0.78em; color: var(--ci-grey); margin-top: 16px; line-height: 1.5; }
.ci-note .ar-line { direction: rtl; display: block; margin-top: 2px; }
